def _get_ute_token_from_file(file_path="/etc/token/ca_ute_artifactory_readonly"):
    """
    Retrieves the UTE token for artifactory downloads from the specified file.

    Args:
      file_path (str, optional): The path to the file containing the UTE artifactory token. Defaults to "/etc/token/ca_ute_artifactory_readonly".

    Returns:
      str: The UTE artifactory token.

    Raises:
      FileNotFoundError: If the specified file does not exist.
    """

    with open(file_path, "r") as file:
        token = file.read().strip()
        return token


def _fetch_file_name_from_artifactory_url(url):
    """
    Fetches the file name from the provided artifactory URL.

    Args:
      url (str): The URL to the file in the artifactory.

    Returns:
      str: The file name.
    """
    return url.split("/")[-1]


def _download_file_from_artifactory(url, save_path):
    """
    Downloads a file from Artifactory.

    Args:
      url (str): The URL of the file in Artifactory.
      save_path (str): The path where the downloaded file will be saved.

    Returns:
      str: The path of the downloaded file.

    Raises:
      Exception: If the file fails to download.
    """

    token = _get_ute_token_from_file()

    subprocess.Popen(["mkdir", "-p", save_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE).communicate()

    filename = _fetch_file_name_from_artifactory_url(url)
    save_path = save_path + "/" + filename

    wget_cmd = ['wget', '-O', str(save_path), "--header='X-JFrog-Art-Api: {}'".format(token),
                str(url)]
    logger.debug('Downloading file with command: {}'.format(' '.join(wget_cmd)))
    print('Downloading file with command: {}'.format(' '.join(wget_cmd)))
    proc = subprocess.Popen(wget_cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    out, err = proc.communicate()
    if proc.returncode != 0:
        raise Exception('File has not been downloaded.\n STDOUT: {}\n STDERR: {}\n RETURN_CODE: {}'.
                        format(out, err, proc.returncode))

    return save_path


def _get_artifactory_url_for_location(location):
    """
    Returns the artifactory URL for the specified site location.

    Args:
      location (str): The location of the artifactory.

    Returns:
      str: The URL of the artifactory.
    """
    if location == "HZ":
        return "https://artifactory-hz1.int.net.nokia.com"
    elif location == "ESP":
        return "https://artifactory-espoo1.int.net.nokia.com"
    else:
        raise ValueError("Unknown location: {}".format(location))
